const icons={grid:'<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></svg>',check:'<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><path d="m5 12 4 4L19 6"/></svg>',calendar:'<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="4" width="18" height="17" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/></svg>',target:'<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="4"/><path d="m15 9 2-2"/></svg>',book:'<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H21"/><path d="M6.5 2H21v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2Z"/></svg>',chart:'<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 3v18h18"/><path d="m7 16 4-5 3 3 5-7"/></svg>',settings:'<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 15.5a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7Z"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-1.8 1.8-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.6v.2h-2.5V20a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1-1.8-1.8.1-.1A1.7 1.7 0 0 0 8.1 15a1.7 1.7 0 0 0-1.6-1H6v-2.5h.5a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9l-.1-.1 1.8-1.8.1.1a1.7 1.7 0 0 0 1.9.3 1.7 1.7 0 0 0 1-1.6V5h2.5v.5a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.1-.1 1.8 1.8-.1.1a1.7 1.7 0 0 0-.3 1.9 1.7 1.7 0 0 0 1.6 1h.5V14h-.5a1.7 1.7 0 0 0-1.6 1Z"/></svg>',search:'<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg>',bell:'<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>',spark:'<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m12 3-1.5 6.5L4 11l6.5 1.5L12 19l1.5-6.5L20 11l-6.5-1.5L12 3Z"/></svg>'};
const seed={org:{id:'org_demo',name:'My Orbit workspace',plan:'Free demo'},user:{name:'',email:'',role:'Owner',goal:'',useCase:''},courses:[],tasks:[],timeBlocks:[],grading:{},focus:0,onboarded:false,tourComplete:false,tourStarted:false,procrastination:{enabled:false,days:3}};
let state=JSON.parse(localStorage.getItem('orbit_demo_v2')||'null')||seed;if(state.org?.name)state.org.name=state.org.name.replace(/workspace$/i,'Workspace');state.timeBlocks ||= [];state.grading ||= {};let view=location.hash.replace('#/','')||'landing';let timer={seconds:25*60,running:false,interval:null,preset:25,mode:'focus',custom:false};
let workloadDetailed=false;
const save=()=>localStorage.setItem('orbit_demo_v2',JSON.stringify(state));const course=id=>state.courses.find(c=>c.id===id)||{name:'Course',code:'Course',color:'#9aa'};const dateLabel=d=>{let dt=new Date(d+'T12:00:00');return {day:dt.getDate(),mon:dt.toLocaleString('en-US',{month:'short'}),full:dt.toLocaleString('en-US',{month:'short',day:'numeric'})}};const today='2026-10-12';
function toast(msg){let el=document.createElement('div');el.className='toast';el.innerHTML='<strong>Orbit</strong> &nbsp;'+msg;document.getElementById('toast-region').appendChild(el);setTimeout(()=>el.remove(),3000)}
function go(v){if(v==='dashboard'&&!state.onboarded){view='onboarding'}else{view=v}location.hash='#/'+view;render()}
function logo(dark=true){return `<div class="brand"><span class="brand-mark"></span><span>orbit</span></div>`}
function initials(name){return (name||'You').split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase()}
function finishOnboarding(){const name=document.getElementById('onboarding-name').value.trim();if(!name){toast('Add your name to continue');return}state.user.name=name;state.user.useCase=document.getElementById('onboarding-use').value;state.user.goal=document.getElementById('onboarding-goal').value.trim();state.org.name=name+'’s Orbit Workspace';state.onboarded=true;save();view='dashboard';location.hash='#/dashboard';render();toast('Your free workspace is ready')}
function showTour(step=0){state.tourStarted=true;save();const steps=[{title:'Welcome to your workspace',body:'This is your Overview: a quick read on what matters today, what is coming up, and the next best action.',tab:'dashboard',button:'Next →'},{title:'Add your classes first',body:'Start by pasting your class list. Orbit will separate each line into its own class so your assignments stay organized.',tab:'courses',button:'Open Classes →'},{title:'Add your first assignment',body:'Now open Planner and create one real assignment with a deadline. The tour will continue when you save it.',tab:'planner',button:'Open Planner →'},{title:'Plan the week',body:'Review the roadmap Orbit created from your real data and see how the workload is distributed.',tab:'roadmap',button:'I reviewed my roadmap →'},{title:'Protect focus time',body:'Open Focus mode to see how Orbit turns your next task into a distraction-free work session.',tab:'focus',button:'Open Focus mode →'},{title:'You are ready',body:'You have seen the core loop: classes, assignments, roadmap, and focus. Analytics will fill in as you work.',tab:'analytics',button:'Finish guided demo'}];const s=steps[step];if(!s)return;let el=document.createElement('div');el.className='tour-backdrop';el.innerHTML='<div class="tour-card"><div class="eyebrow">Guided demo · '+(step+1)+' of '+steps.length+'</div><h2>'+s.title+'</h2><p>'+s.body+'</p><div class="tour-progress">'+steps.map((_,i)=>'<span class="'+(i<=step?'active':'')+'"></span>').join('')+'</div><div class="modal-foot"><button class="secondary" onclick="closeTour()">Skip tour</button><button class="primary" onclick="tourAction('+step+')">'+s.button+'</button></div></div>';document.body.appendChild(el);if(view!==s.tab&&!(step===1&&view==='courses')&&!(step===2&&view==='planner')){closeTour();go(s.tab);setTimeout(()=>showTour(step),250)}}
function tourAction(step){if(step===0){closeTour();showTour(1);return}if(step===1){closeTour();go('courses');toast('Click Paste course list to add your courses');return}if(step===2){closeTour();go('planner');toast('Click ＋ Add assignment to create your first task');return}if(step===3){closeTour();showTour(4);return}if(step===4){closeTour();showTour(5);return}state.tourComplete=true;state.tourStarted=true;save();closeTour();go('dashboard');toast('Guided demo complete — your workspace is ready')}
function closeTour(){document.querySelector('.tour-backdrop')?.remove()}
function dashboardFresh(){let open=state.tasks.filter(t=>t.status!=='done'),rec=open.length?[...open].sort(score)[0]:null;return '<div class="page-head"><div><div class="eyebrow">Your workspace</div><h1>Welcome, '+state.user.name+' <span style="font-size:25px">✦</span></h1><p>'+ (state.user.goal||'Add your first assignment and let Orbit help you find your next step.')+'</p></div><div class="page-actions"><button class="secondary" onclick="showTour(0)">Take the guided tour</button><button class="primary" onclick="openModal()">＋ New assignment</button></div></div><div class="grid grid-4"><div class="card stat-card"><div class="stat-top">Open tasks</div><div class="stat-value">'+open.length+'</div><div class="stat-foot">Your plan starts here</div></div><div class="card stat-card"><div class="stat-top">On-time rate</div><div class="stat-value">—</div><div class="stat-foot">Complete tasks to build your trend</div></div><div class="card stat-card"><div class="stat-top">Focus this week</div><div class="stat-value">'+Math.floor(state.focus/60)+'m</div><div class="stat-foot">Your focus goal is waiting</div></div><div class="card stat-card"><div class="stat-top">Semester progress</div><div class="stat-value">'+(open.length?'0%':'—')+'</div><div class="progress"><span style="width:0%"></span></div></div></div><div class="dash-grid"><div class="card"><div class="card-title"><h2>Today’s priorities</h2><a onclick="go(\'planner\')">See all →</a></div>'+(open.length?open.slice(0,4).map(taskRow).join(''):'<div class="empty">Your priority list is clear. Add an assignment to get a recommendation.</div>')+'</div><div class="recommendation"><div class="rec-label">'+icons.spark+' &nbsp; Orbit recommends</div><h3>'+(rec?rec.title:'Start with one small step')+'</h3><p>'+(rec?reason(rec):'Add a task with a deadline and Orbit will explain what to do next and why.')+'</p><button class="rec-button" onclick="'+(rec?'openModal()':'openModal()')+'">'+(rec?'Adjust your plan':'Add your first assignment')+' →</button></div></div><div class="dash-grid"><div class="card"><div class="card-title"><h2>This week’s workload</h2><a onclick="go(\'roadmap\')">Open roadmap →</a></div>'+workload()+'</div><div class="card"><div class="card-title"><h2>Coming up</h2><a onclick="go(\'planner\')">View planner →</a></div><div class="empty">Deadlines you add will appear here.</div></div></div>'}
function appShellFresh(){let nav=[['dashboard','Overview','grid'],['planner','Planner','check'],['roadmap','Roadmap','calendar'],['focus','Focus mode','target'],['courses','Courses','book'],['analytics','Analytics','chart']];return '<div class="app-shell"><aside class="sidebar">'+logo()+'<button class="workspace-switch" onclick="go(\'settings\')"><span class="avatar">'+initials(state.user.name)+'</span><span><small>Workspace</small><strong>'+state.org.name+'</strong></span></button><div class="nav-label">Workspace</div>'+nav.map(n=>'<button class="nav-link '+(view===n[0]?'active':'')+'" data-tour="'+n[0]+'" onclick="go(\''+n[0]+'\')">'+icons[n[2]]+'<span>'+n[1]+'</span></button>').join('')+'<div class="nav-label">Manage</div><button class="nav-link '+(view==='settings'?'active':'')+'" onclick="go(\'settings\')">'+icons.settings+'<span>Settings</span></button><div class="side-bottom"><div class="profile"><span class="avatar">'+initials(state.user.name)+'</span><span class="profile-info"><b style="font-size:12px;color:#fff">'+state.user.name+'</b><small>Free demo workspace</small></span></div></div></aside><main class="main"><header class="topbar"><div class="crumb"><span>Workspace</span> <span style="margin:0 6px;color:#c1cad7">/</span> <strong>'+(({dashboard:'Overview',planner:'Assignment planner',roadmap:'Weekly roadmap',focus:'Focus mode',courses:'Courses',analytics:'Analytics',settings:'Settings'})[view]||'Overview')+'</strong></div><div class="top-actions"><button class="icon-btn" onclick="toast(\'You are all caught up\')">'+icons.bell+'</button><button class="secondary" onclick="showTour(0)">? Guided tour</button><button class="secondary" onclick="openModal()">＋ Add task</button><button class="primary" onclick="go(\'focus\')">'+icons.target+' Start focus</button></div></header><div class="content">'+({dashboard:dashboardFresh,planner:planner,roadmap:roadmap,focus:focus,courses:courses,analytics:analytics,settings:settings}[view]||dashboardFresh)()+'</div></main></div>'}
function plannerFresh(){return '<div class="page-head"><div><div class="eyebrow">Your workload, made workable</div><h1>Assignment planner</h1><p>Every deadline in one calm, prioritized view.</p></div><div class="page-actions"><button class="secondary" onclick="openImportModal()">↥ Paste from Canvas</button><button class="primary" onclick="openModal()">＋ Add assignment</button></div></div><div class="card"><div class="toolbar"><div class="search">'+icons.search+'<input id="task-search" placeholder="Search assignments..." oninput="filterTasks()"></div><div class="filters"><select id="course-filter" onchange="filterTasks()"><option value="all">All courses</option>'+state.courses.map(c=>'<option value="'+c.id+'">'+c.code+'</option>').join('')+'</select><select id="status-filter" onchange="filterTasks()"><option value="all">All status</option><option value="todo">In progress</option><option value="done">Completed</option></select><select id="priority-filter" onchange="filterTasks()"><option value="all">All priority</option><option>High</option><option>Medium</option><option>Low</option></select></div></div><div id="task-table"><table class="table"><thead><tr><th style="width:40%">Assignment</th><th>Course</th><th>Due date</th><th>Time</th><th>Priority</th><th></th></tr></thead><tbody>'+state.tasks.map(tableTask).join('')+'</tbody></table>'+(state.tasks.length?'':'<div class="empty">No assignments yet. Add one manually or paste your Canvas assignment list.</div>')+'</div></div>'}
function parseImportedAssignments(text){const clean=text.replace(/\r/g,' ').replace(/\n+/g,' ').replace(/\s+/g,' ').replace(/\bsvg\b/gi,'');const pattern=/\[\*\*(.+?)\*\*\]\((https?:\/\/[^)]+)\)\s*([^|]+?)\|\s*\[Go to course\]\([^)]+\)\s*(\d+)\s*pts\s*\*\*(\d{1,2}\/\d{1,2}\/\d{4})\s+(\d{1,2}:\d{2}\s*[AP]M)\*\*/gi;let matches=[],m;while((m=pattern.exec(clean))){const courseText=m[3].trim();const codeMatch=courseText.match(/^(.+?)(?:\s*\([^)]*\))?\s+([^()]+)$/);const code=(codeMatch?codeMatch[1]:courseText).trim();const courseName=(codeMatch?codeMatch[2]:courseText).trim();const [month,day,year]=m[5].split('/');const iso=year+'-'+month.padStart(2,'0')+'-'+day.padStart(2,'0');matches.push({title:m[1].trim(),url:m[2],courseCode:code,courseName,due:iso,displayDue:m[5]+' '+m[6],points:+m[4]})}return matches}
function openImportModal(){let m=document.createElement('div');m.className='modal-backdrop';m.id='import-modal';m.innerHTML='<div class="modal import-modal"><h2>Paste assignments</h2><p>Copy your assignment list from Canvas and paste it below. Orbit will extract titles, courses, points, and due dates.</p><div class="field"><label>Canvas assignment text</label><textarea id="import-text" placeholder="Paste your Canvas assignment list here..." style="min-height:150px"></textarea></div><div id="import-preview" class="import-preview hidden"></div><div class="modal-foot"><button class="secondary" onclick="document.getElementById(\'import-modal\').remove()">Cancel</button><button class="secondary" onclick="previewImport()">Preview</button><button class="primary" onclick="importAssignments()">Import assignments →</button></div></div>';document.body.appendChild(m)}
function previewImport(){const parsed=parseImportedAssignments(document.getElementById('import-text').value);const box=document.getElementById('import-preview');box.classList.remove('hidden');box.innerHTML=parsed.length?'<b>'+parsed.length+' assignments found</b>'+parsed.map(x=>'<div class="import-row"><span>'+x.title+'</span><small>'+x.courseCode+' · '+x.displayDue+'</small></div>').join(''):'<span>No assignments found yet. Make sure the pasted text includes the Canvas title, course, points, and due date.'}
function importAssignments(){const parsed=parseImportedAssignments(document.getElementById('import-text').value);if(!parsed.length){toast('Preview could not find any assignments');return}parsed.forEach(item=>{let c=state.courses.find(x=>x.code.toLowerCase()===item.courseCode.toLowerCase());if(!c){c={id:'c'+Date.now()+Math.random().toString(16).slice(2),name:item.courseName,code:item.courseCode,color:['#79a9ff','#c29cff','#ffad72','#65d6b0'][state.courses.length%4],teacher:'Imported from Canvas'};state.courses.push(c)}state.tasks.push({id:'t'+Date.now()+Math.random().toString(16).slice(2),title:item.title,type:'Assignment',course:c.id,due:item.due,estimate:60,difficulty:3,priority:'Medium',status:'todo',progress:0,subtasks:1,points:item.points,externalUrl:item.url})});save();document.getElementById('import-modal').remove();render();toast(parsed.length+' assignment'+(parsed.length===1?'':'s')+' imported from Canvas')}
function parseCourseList(text){return text.split(/\r?\n/).map(line=>line.replace(/^\s*[-•*]\s*/,'').replace(/^\[([^\]]+)\]\([^)]+\)\s*/,'').replace(/\s+/g,' ').trim()).filter(Boolean).map(line=>{const codeMatch=line.match(/^([A-Z]{2,6}\s*\d{3,5}(?:\.\d+)?)/i);const code=codeMatch?codeMatch[1].replace(/\s+/g,' ').trim():'CLASS';const name=codeMatch?line.slice(codeMatch[1].length).replace(/^\s*(?:\([^)]*\))?\s*/,'').trim()||line:line;return {code,name}}).filter(x=>x.name)}
function openCourseImportModal(){let m=document.createElement('div');m.className='modal-backdrop';m.id='course-import-modal';m.innerHTML='<div class="modal"><h2>Add your courses</h2><p>Paste one course per line. Orbit will split the list and create a course card for each one.</p><div class="field"><label>Course list</label><textarea id="course-import-text" placeholder="CS 4800.01 (F26-Regular) Software Engineering&#10;CS 4230.01 (F26-Regular) Social Computing" style="min-height:150px"></textarea></div><div id="course-import-preview" class="import-preview hidden"></div><div class="modal-foot"><button class="secondary" onclick="document.getElementById(\'course-import-modal\').remove()">Cancel</button><button class="secondary" onclick="previewCourseImport()">Preview</button><button class="primary" onclick="importCourses()">Add courses →</button></div></div>';document.body.appendChild(m)}
function previewCourseImport(){const parsed=parseCourseList(document.getElementById('course-import-text').value);const box=document.getElementById('course-import-preview');box.classList.remove('hidden');box.innerHTML=parsed.length?'<b>'+parsed.length+' courses found</b>'+parsed.map(x=>'<div class="import-row"><span>'+x.name+'</span><small>'+x.code+'</small></div>').join(''):'<span>No courses found. Paste one course per line.</span>'}
function importCourses(){const parsed=parseCourseList(document.getElementById('course-import-text').value);if(!parsed.length){toast('Paste at least one course to continue');return}parsed.forEach(item=>{if(!state.courses.some(c=>c.code.toLowerCase()===item.code.toLowerCase()))state.courses.push({id:'c'+Date.now()+Math.random().toString(16).slice(2),name:item.name,code:item.code,color:['#79a9ff','#c29cff','#ffad72','#65d6b0'][state.courses.length%4],teacher:'Added by you'})});save();document.getElementById('course-import-modal').remove();render();toast(parsed.length+' course'+(parsed.length===1?'':'s')+' added');if(state.tourStarted&&!state.tourComplete&&state.courses.length>0){setTimeout(()=>showTour(2),400)}}
function coursesFresh(){return '<div class="page-head"><div><div class="eyebrow">Your academic orbit</div><h1>Courses</h1><p>Start with your course list, then attach assignments to the right place.</p></div><div class="page-actions"><button class="secondary" onclick="openCourseImportModal()">↥ Paste course list</button><button class="primary" onclick="toast(\'Use Paste course list to add your first course\')">＋ Add course</button></div></div>'+(state.courses.length?'<div class="grid grid-3">'+state.courses.map(c=>{let ts=state.tasks.filter(t=>t.course===c.id),pct=ts.length?Math.round(ts.reduce((a,t)=>a+t.progress,0)/ts.length):0;return '<div class="card course-card"><div class="course-banner" style="background:'+c.color+'"></div><h3>'+c.name+'</h3><p>'+c.code+' · '+c.teacher+'</p><div style="margin-top:22px"><div class="stat-top">Course progress <b style="color:var(--navy)">'+pct+'%</b></div><div class="progress" style="margin-top:8px"><span style="width:'+pct+'%;background:'+c.color+'"></span></div></div><div class="course-meta"><span>'+ts.length+' assignments</span><span>'+(!ts.length?'Ready for work':'In progress')+'</span></div></div>'}).join('')+'</div>':'<div class="card empty-course"><div class="empty">No courses yet. Paste your course list to build your workspace in seconds.</div></div>')}
function openClassModal(){let m=document.createElement('div');m.className='modal-backdrop';m.id='class-modal';m.innerHTML='<div class="modal"><h2>Add a class</h2><p>Add one class manually, or use Paste class list to add several at once.</p><div class="field"><label>Class name</label><input id="class-name" placeholder="e.g. Software Engineering"></div><div class="field" style="margin-top:12px"><label>Class code</label><input id="class-code" placeholder="e.g. CS 4800.01"></div><div class="field" style="margin-top:12px"><label>Instructor (optional)</label><input id="class-teacher" placeholder="e.g. Professor Smith"></div><div class="modal-foot"><button class="secondary" onclick="document.getElementById(\'class-modal\').remove()">Cancel</button><button class="primary" onclick="addClass()">Add class →</button></div></div>';document.body.appendChild(m)}
function addClass(){const name=document.getElementById('class-name').value.trim(),code=document.getElementById('class-code').value.trim()||'CLASS';if(!name){toast('Add a class name to continue');return}state.courses.push({id:'c'+Date.now(),name,code,teacher:document.getElementById('class-teacher').value.trim()||'Added by you',color:['#79a9ff','#c29cff','#ffad72','#65d6b0'][state.courses.length%4]});save();document.getElementById('class-modal').remove();render();toast('Class added')}
function classWeights(id){return state.grading[id]||{exam:40,project:30,quiz:15,homework:15}}
function updateWeight(id,key,value){state.grading[id] ||= {exam:40,project:30,quiz:15,homework:15};state.grading[id][key]=Math.max(0,Math.min(100,+value||0));save()}
function priorityForAssignment(courseId,title,type){const weights=classWeights(courseId),text=((title||'')+' '+(type||'')).toLowerCase();let category=text.includes('exam')||text.includes('midterm')||text.includes('final')?'exam':text.includes('project')||text.includes('paper')||text.includes('essay')?'project':text.includes('quiz')?'quiz':'homework',weight=weights[category]||0;return weight>=35?'High':weight>=20?'Medium':'Low'}
function setNewPriorityAuto(){const courseId=document.getElementById('new-course').value,title=document.getElementById('new-title').value,type='Assignment',priority=priorityForAssignment(courseId,title,type);document.getElementById('new-priority').value=priority;toast('Priority set to '+priority+' based on class grading')}
function priorityCard(c){const w=classWeights(c.id),total=w.exam+w.project+w.quiz+w.homework;return `<div class="card priority-card"><div class="priority-card-head"><div><span class="course-dot" style="background:${c.color}"></span><h2>${c.name}</h2><p>${c.code} · Current weighting: ${total}%</p></div><span class="pill ${total===100?'low':'medium'}">${total===100?'Balanced':'Check total'}</span></div><div class="weight-grid"><label>Exams <input type="number" min="0" max="100" value="${w.exam}" onchange="updateWeight('${c.id}','exam',this.value)"><small>%</small></label><label>Projects / papers <input type="number" min="0" max="100" value="${w.project}" onchange="updateWeight('${c.id}','project',this.value)"><small>%</small></label><label>Quizzes <input type="number" min="0" max="100" value="${w.quiz}" onchange="updateWeight('${c.id}','quiz',this.value)"><small>%</small></label><label>Homework <input type="number" min="0" max="100" value="${w.homework}" onchange="updateWeight('${c.id}','homework',this.value)"><small>%</small></label></div><div class="reason-box">${total===100?'Auto-set will prioritize higher-impact work first.':'These weights add up to '+total+'%. Adjust them to 100% for clearer recommendations.'}</div></div>`}
function priorityFresh(){const cards=state.courses.map(priorityCard).join('');return `<div class="page-head"><div><div class="eyebrow">Make recommendations fit your classes</div><h1>Priority adjuster</h1><p>Set grading weights for each class so Orbit knows what work carries the most impact.</p></div><button class="secondary" onclick="toast('Weights are saved automatically')">Auto-saved</button></div>${cards||'<div class="card empty-state-large"><div class="empty">Add your classes first, then set their grading weights here.</div></div>'}`}
function roadmapFresh(){return '<div class="page-head"><div><div class="eyebrow">Your next seven days</div><h1>Weekly roadmap</h1><p>Orbit will distribute your assignments across a clear calendar.</p></div><div class="page-actions"><button class="secondary" onclick="toast(\'Week view is coming soon\')">Week view</button><button class="primary" onclick="go(\'planner\')">＋ Add work</button></div></div><div class="card calendar-card"><div class="calendar-toolbar"><button class="icon-btn" onclick="toast(\'Previous month\')">‹</button><h2>October 2026</h2><button class="icon-btn" onclick="toast(\'Next month\')">›</button></div><div class="calendar-grid calendar-weekdays">'+['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>'<div>'+d+'</div>').join('')+'</div><div class="calendar-grid">'+calendarCells()+'</div><div class="calendar-legend"><span><i style="background:#79a9ff"></i> Class assignment</span><span><i style="background:var(--mint-strong)"></i> Personal target</span></div></div>'}
function calendarCells(){const year=2026,month=9,first=new Date(year,month,1).getDay(),days=new Date(year,month+1,0).getDate();let cells=[];for(let i=0;i<first;i++)cells.push('<div class="calendar-day muted-day"></div>');for(let day=1;day<=days;day++){const iso=year+'-10-'+String(day).padStart(2,'0'),items=state.tasks.filter(t=>t.due===iso);cells.push('<div class="calendar-day '+(iso===today?'today-day':'')+'"><b>'+day+'</b>'+(items.length?items.map(t=>'<button class="calendar-task" style="border-left-color:'+course(t.course).color+'" onclick="go(\'planner\')" title="'+t.title+'">'+t.title+'</button>').join(''):'')+'</div>')}return cells.join('')}
function timePlannerFresh(){const days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'],hours=Array.from({length:15},(_,i)=>i+8);return '<div class="page-head"><div><div class="eyebrow">Shape the time around your work</div><h1>Time planner</h1><p>Block classes, commitments, study sessions, and homework into a schedule you can actually follow.</p></div><button class="primary" onclick="openTimeBlockModal()">＋ Add time block</button></div><div class="card hourly-card"><div class="hourly-grid hourly-head"><div></div>'+days.map(d=>'<div>'+d+'</div>').join('')+'</div><div class="hourly-grid">'+hours.map(hour=>'<div class="hour-label">'+formatHour(hour)+'</div>'+days.map((_,day)=>{const blocks=state.timeBlocks.filter(b=>b.day===day&&Number(b.start.split(':')[0])===hour);return '<div class="hour-cell">'+blocks.map(b=>'<button class="time-block '+b.kind+'" title="'+b.title+'" onclick="toast(\''+b.title.replace(/'/g,"\\'")+'\')"><b>'+b.title+'</b><small>'+b.start+'–'+b.end+'</small></button>').join('')+'</div>'}).join('')).join('')+'</div></div><div class="time-planner-note"><span>${icons.spark}</span><div><b>Plan around your fixed commitments first.</b><p>Once classes and other blocks are in place, use Planner and Roadmap to fit study time into the gaps.</p></div></div>'}
function formatHour(hour){const suffix=hour>=12?'PM':'AM',display=hour>12?hour-12:hour===0?12:hour;return display+':00 '+suffix}
function openTimeBlockModal(){let m=document.createElement('div');m.className='modal-backdrop';m.id='time-block-modal';m.innerHTML='<div class="modal"><h2>Add a time block</h2><p>Tell Orbit when you are unavailable or when you want to protect study time.</p><div class="form-grid"><div class="field full"><label>What is this block?</label><input id="block-title" placeholder="e.g. CS 4800 lecture or study for midterm"></div><div class="field"><label>Day</label><select id="block-day">'+['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((d,i)=>'<option value="'+i+'">'+d+'</option>').join('')+'</select></div><div class="field"><label>Type</label><select id="block-kind"><option value="class">Class</option><option value="study">Study</option><option value="work">Work</option><option value="personal">Personal</option></select></div><div class="field"><label>Start</label><input id="block-start" type="time" value="09:00"></div><div class="field"><label>End</label><input id="block-end" type="time" value="10:00"></div></div><div class="modal-foot"><button class="secondary" onclick="document.getElementById(\'time-block-modal\').remove()">Cancel</button><button class="primary" onclick="addTimeBlock()">Add block →</button></div></div>';document.body.appendChild(m)}
function addTimeBlock(){const title=document.getElementById('block-title').value.trim(),start=document.getElementById('block-start').value,end=document.getElementById('block-end').value;if(!title||!start||!end){toast('Add a title, start time, and end time');return}if(end<=start){toast('End time must be after start time');return}state.timeBlocks.push({id:'b'+Date.now(),title,day:+document.getElementById('block-day').value,kind:document.getElementById('block-kind').value,start,end});save();document.getElementById('time-block-modal').remove();render();toast('Time block added')}
function focusFresh(){return '<div class="page-head"><div><div class="eyebrow">Protect your attention</div><h1>Focus mode</h1><p>Start a session when you are ready to work on something real.</p></div></div><div class="grid grid-2"><div class="focus-card card"><div class="timer">25:00</div><div class="timer-label">Ready when you are</div><div class="timer-controls"><button onclick="toggleTimer()">Start session</button><button class="secondary-dark" onclick="resetTimer()">Reset</button></div></div><div class="card empty-state-large"><div class="empty">Choose an assignment in Planner, then start a focus session. Your statistics will appear here after you complete real sessions.</div></div></div>'}
function analyticsFresh(){return '<div class="page-head"><div><div class="eyebrow">Your momentum, measured</div><h1>Analytics</h1><p>Orbit will turn your completed work and focus sessions into useful patterns.</p></div></div><div class="card empty-state-large"><div class="empty">No analytics yet. Add courses and assignments, complete a task, or finish a focus session to start building your personal productivity picture.</div></div>'}
function focusFlexible(){let mins=Math.floor(timer.seconds/60).toString().padStart(2,'0'),secs=(timer.seconds%60).toString().padStart(2,'0'),isBreak=timer.mode==='break';return '<div class="page-head"><div><div class="eyebrow">Protect your attention</div><h1>Focus mode</h1><p>Choose a work block or a break that fits your energy.</p></div><button class="secondary" onclick="toast(\'Focus preferences saved for this session\')">⚙ Preferences</button></div><div class="grid grid-2"><div class="focus-card card"><div class="timer">'+mins+':'+secs+'</div><div class="timer-label">'+(isBreak?'Break time · recharge before the next block':timer.running?'Deep work in progress':'Ready when you are')+'</div><div class="timer-controls"><button onclick="toggleTimer()">'+(timer.running?'Pause':isBreak?'Start break':'Start focus')+'</button><button class="secondary-dark" onclick="resetTimer()">Reset</button></div></div><div class="card"><div class="card-title"><h2>Session length</h2><span class="pill '+(isBreak?'low':'blue')+'">'+(isBreak?'Break':'Focus')+'</span></div><div class="timer-options"><button class="timer-option '+(!isBreak&&timer.preset===25?'selected':'')+'" onclick="setTimer(25,\'focus\')"><b>25 min</b><span>Classic Pomodoro</span></button><button class="timer-option '+(!isBreak&&timer.preset===60?'selected':'')+'" onclick="setTimer(60,\'focus\')"><b>1 hour</b><span>Deep work block</span></button><button class="timer-option '+(!isBreak&&timer.custom?'selected':'')+'" onclick="openCustomTimer(\'focus\')"><b>Custom</b><span>Choose your minutes</span></button></div><div class="card-title" style="margin-top:25px"><h2>Break length</h2><span class="pill low">Recovery</span></div><div class="timer-options"><button class="timer-option '+(isBreak&&timer.preset===10?'selected':'')+'" onclick="setTimer(10,\'break\')"><b>10 min</b><span>Quick reset</span></button><button class="timer-option '+(isBreak&&timer.preset===15?'selected':'')+'" onclick="setTimer(15,\'break\')"><b>15 min</b><span>Longer recharge</span></button><button class="timer-option '+(isBreak&&timer.custom?'selected':'')+'" onclick="openCustomTimer(\'break\')"><b>Custom</b><span>Choose your minutes</span></button></div></div></div><div class="grid grid-3" style="margin-top:18px"><div class="mini-stat"><span>Focus today</span><b>'+Math.floor(state.focus/60)+'m</b><span>Complete sessions to build your total</span></div><div class="mini-stat"><span>Current mode</span><b>'+(isBreak?'Break':'Focus')+'</b><span>'+(timer.preset||25)+' minute block</span></div><div class="mini-stat"><span>Sessions completed</span><b>0</b><span>Your history will appear here</span></div></div>'}
function setTimer(minutes,mode){clearInterval(timer.interval);timer.running=false;timer.seconds=minutes*60;timer.preset=minutes;timer.mode=mode;timer.custom=false;render()}
function openCustomTimer(mode){let m=document.createElement('div');m.className='modal-backdrop';m.id='custom-timer-modal';m.innerHTML='<div class="modal"><h2>Set a custom '+(mode==='break'?'break':'focus')+' timer</h2><p>Choose any duration from 1 to 180 minutes.</p><div class="field"><label>Minutes</label><input id="custom-minutes" type="number" min="1" max="180" value="'+(mode==='break'?20:45)+'"></div><div class="modal-foot"><button class="secondary" onclick="document.getElementById(\'custom-timer-modal\').remove()">Cancel</button><button class="primary" onclick="applyCustomTimer(\''+mode+'\')">Set timer →</button></div></div>';document.body.appendChild(m)}
function applyCustomTimer(mode){let minutes=+document.getElementById('custom-minutes').value;if(!minutes||minutes<1||minutes>180){toast('Choose between 1 and 180 minutes');return}document.getElementById('custom-timer-modal').remove();clearInterval(timer.interval);timer.running=false;timer.seconds=minutes*60;timer.preset=minutes;timer.mode=mode;timer.custom=true;render();toast('Custom '+(mode==='break'?'break':'focus')+' set for '+minutes+' minutes')}
function plannerWithShield(){return plannerFresh().replace('All courses','All classes').replace('<button class="primary" onclick="openModal()">＋ Add assignment</button>','<button class="secondary" onclick="openShieldModal()">⏱ '+(state.procrastination?.enabled?'Shield on':'Beat procrastination')+'</button><button class="primary" onclick="openModal()">＋ Add assignment</button>')}
function shiftDate(date,days){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)}
function openShieldModal(){const current=state.procrastination?.days||3;let m=document.createElement('div');m.className='modal-backdrop';m.id='shield-modal';m.innerHTML='<div class="modal"><h2>Beat procrastination</h2><p>Orbit can create earlier personal deadlines while keeping the real due date visible in your data. Choose how much breathing room you want.</p><div class="field"><label>Move personal deadlines earlier by</label><select id="shield-days"><option value="1" '+(current===1?'selected':'')+'>1 day</option><option value="3" '+(current===3?'selected':'')+'>3 days</option><option value="5" '+(current===5?'selected':'')+'>5 days</option><option value="7" '+(current===7?'selected':'')+'>1 week</option></select></div><div class="reason-box" style="margin-top:15px">Example: if the real deadline is October 19, Orbit sets your personal target to October 16. October 19 stays the official due date, giving you three days to review, fix issues, and submit on time.</div><div class="modal-foot"><button class="secondary" onclick="document.getElementById(\'shield-modal\').remove()">Cancel</button><button class="primary" onclick="applyShield()">'+(state.procrastination?.enabled?'Update shield':'Enable shield')+' →</button></div></div>';document.body.appendChild(m)}
function applyShield(){const days=+document.getElementById('shield-days').value;state.procrastination={enabled:true,days};state.tasks.forEach(t=>{if(!t.realDue)t.realDue=t.due;t.due=shiftDate(t.realDue,-days)});save();document.getElementById('shield-modal').remove();render();toast('Personal deadlines moved '+days+' day'+(days===1?'':'s')+' earlier')}
function disableShield(){if(!state.procrastination?.enabled)return;state.tasks.forEach(t=>{if(t.realDue){t.due=t.realDue;delete t.realDue}});state.procrastination={enabled:false,days:state.procrastination.days||3};save();render();toast('Real deadlines restored')}
function settingsFresh(){return '<div class="page-head"><div><div class="eyebrow">Workspace controls</div><h1>Settings</h1><p>Update your profile and keep your demo workspace personal.</p></div></div><div class="card"><div class="settings-nav"><button class="settings-tab active">Profile</button><button class="settings-tab" onclick="toast(\'Team features are available in the full version\')">Members</button><button class="settings-tab" onclick="toast(\'Billing is hidden in the free demo\')">Plan</button></div><div class="grid grid-2"><div><h2 style="font-family:Space Grotesk;font-size:17px;color:var(--navy)">Your profile</h2><div class="field" style="margin:15px 0"><label>Name</label><input value="'+state.user.name+'" onchange="state.user.name=this.value;save();render();toast(\'Profile updated\')"></div><div class="field"><label>What you’re working toward</label><textarea onchange="state.user.goal=this.value;save();toast(\'Goal updated\')">'+(state.user.goal||'')+'</textarea></div><button class="primary" style="margin-top:17px" onclick="toast(\'Profile saved\')">Save changes</button></div><div><h2 style="font-family:Space Grotesk;font-size:17px;color:var(--navy)">Free demo workspace</h2><p style="font-size:12px;line-height:1.6;color:var(--muted)">This demo is intentionally free and starts with a clean slate. Add your own courses and assignments to see Orbit adapt.</p><div class="reason-box">No payment details. No locked screens. Just the full product walkthrough.</div><button class="secondary" style="margin-top:15px" onclick="showTour(0)">Replay guided tour</button></div></div></div><div class="card shield-card"><div><div class="eyebrow">Optional planning support</div><h2 style="font-family:Space Grotesk;font-size:17px;color:var(--navy);margin:6px 0">Procrastination shield</h2><p style="font-size:12px;line-height:1.6;color:var(--muted);margin:0">Create earlier personal deadlines while preserving each real deadline. '+(state.procrastination?.enabled?'Currently moving tasks '+state.procrastination.days+' days earlier.':'Currently off.')+'</p></div><div class="shield-actions"><button class="secondary" onclick="openShieldModal()">'+(state.procrastination?.enabled?'Adjust buffer':'Set earlier deadlines')+'</button>'+(state.procrastination?.enabled?'<button class="secondary" onclick="disableShield()">Turn off</button>':'')+'</div></div>'}
planner = plannerWithShield;
courses = coursesFresh;
roadmap = roadmapFresh;
focus = focusFlexible;
analytics = analyticsFresh;
timePlannerFresh=(()=>{const base=timePlannerFresh;return ()=>base().replace('${icons.spark}',icons.spark)})();
const baseDashboard=dashboardFresh;dashboard = ()=>baseDashboard().replace('<button class="secondary" onclick="showTour(0)">Take the guided tour</button>','');dashboardFresh=dashboard;
const baseWorkload=workload;workload=()=>state.tasks.length?baseWorkload():'<div class="empty">Your weekly workload will appear here after you add assignments.</div>';
workload=workloadEnhanced;
appShellFresh=(()=>{const base=appShellFresh;return ()=>{let html=base().replace('? Guided tour','Guided tour').replace('>Courses</span>','>Classes</span>').replace('Workspace / Courses','Workspace / Classes').replace('<div class="nav-label">Manage</div>','<button class="nav-link '+(view==='timeplanner'?'active':'')+'" onclick="go(\'timeplanner\')">'+icons.calendar+'<span>Time planner</span></button><button class="nav-link '+(view==='priority'?'active':'')+'" onclick="go(\'priority\')">'+icons.spark+'<span>Priority adjuster</span></button><div class="nav-label">Manage</div>');if(view==='priority'||view==='timeplanner'){const start=html.indexOf('<div class="content">'),end=html.lastIndexOf('</main>'),page=view==='priority'?priorityFresh():timePlannerFresh();html=html.slice(0,start)+'<div class="content">'+page+'</div>'+html.slice(end);html=html.replace('<strong>Overview</strong>','<strong>'+ (view==='priority'?'Priority adjuster':'Time planner') +'</strong>')}return html}})();
courses=()=>coursesFresh().replace('Courses</h1>','Classes</h1>').replace('Courses</strong>','Classes</strong>').replace('course list','class list').replace('course</h3>','class</h3>').replace('course to build','class to build').replace('onclick="toast(\'Use Paste course list to add your first course\')"','onclick="openClassModal()"').replace('＋ Add course','＋ Add class');
settings = ()=>settingsFresh().replace('<button class="secondary" style="margin-top:15px" onclick="showTour(0)">Replay guided tour</button>','');
const baseOpenModal=openModal;openModal=()=>{baseOpenModal();const select=document.getElementById('new-priority');if(select){const option=document.createElement('option');option.value='auto';option.textContent='Auto-set from class grading';select.insertBefore(option,select.firstChild);select.value='auto';select.insertAdjacentHTML('beforebegin','<button class="auto-priority" type="button" onclick="setNewPriorityAuto()">✦ Auto-set from class grading</button>')}};
const baseAddTask=addTask;addTask=()=>{const select=document.getElementById('new-priority');if(select&&select.value==='auto')setNewPriorityAuto();baseAddTask()};
function render(){document.body.classList.toggle('tour-complete',!!state.tourComplete);const root=document.getElementById('app');if(view==='landing'){root.innerHTML=landing();return}if(view==='onboarding'||view==='login'){root.innerHTML=onboarding();return}if(!state.onboarded){view='onboarding';root.innerHTML=onboarding();return}root.innerHTML=appShellFresh();bind();if(!state.tourComplete&&!state.tourStarted&&view==='dashboard'){state.tourStarted=true;save();setTimeout(()=>showTour(0),300);}}
function landing(){return `<div class="landing"><nav class="landing-nav">${logo()}<div class="landing-nav-links"><a onclick="document.getElementById('features').scrollIntoView()">Product</a><a onclick="document.getElementById('features').scrollIntoView()">How it works</a><button class="secondary" onclick="go('onboarding')">Open free demo</button></div></nav><section class="landing-hero"><div><div class="eyebrow">A calmer command center for your semester</div><h1>Make progress feel <span>inevitable.</span></h1><p>Orbit turns a messy list of deadlines into a clear next step—so you spend less time planning and more time learning.</p><div class="landing-cta"><button class="primary" onclick="go('onboarding')">Start the free demo <span>→</span></button><button class="secondary" onclick="document.getElementById('features').scrollIntoView()">See how it works</button></div><div class="hero-note"><span>${icons.check}</span> Free interactive demo · Personalize it in under a minute</div></div><div class="preview"><div class="preview-top"><i></i><i></i><i></i></div><div class="preview-body"><div class="preview-side"><b>orbit</b><div></div><div></div><div></div><div></div></div><div class="preview-main"><h4>Your next best action</h4><div class="preview-stats"><div class="preview-stat"><b>Plan</b><small>your week</small></div><div class="preview-stat"><b>Focus</b><small>on one thing</small></div><div class="preview-stat"><b>Track</b><small>your progress</small></div></div><div class="preview-box"><b>Personalized roadmap</b><div class="fake-line"></div><div class="fake-line short"></div></div><div class="preview-box"><b>One clear next step</b><div class="fake-line"></div><div class="fake-line"></div></div></div></div></div></section><section class="landing-section" id="features"><div class="landing-section-inner"><div class="eyebrow">Less overwhelm. More momentum.</div><h2>Everything your semester needs<br>to stay in orbit.</h2><p class="section-lead">A thoughtful workspace for planning, prioritizing, and protecting the time that makes progress happen.</p><div class="feature-grid"><div class="feature-card"><div class="feature-icon">${icons.spark}</div><h3>Know what to do next</h3><p>Transparent recommendations weigh urgency, effort, difficulty, and progress to surface the right task at the right time.</p></div><div class="feature-card"><div class="feature-icon">${icons.target}</div><h3>Break big work down</h3><p>Turn intimidating projects into small, satisfying steps and watch your progress compound.</p></div><div class="feature-card"><div class="feature-icon">${icons.calendar}</div><h3>Make time for focus</h3><p>Plan a realistic week, then step into a distraction-free session built around the work in front of you.</p></div></div><div class="free-demo-banner"><div><div class="eyebrow">Try it yourself</div><h3>Free demo workspace</h3><p>Set your own name and goal, then see how Orbit helps you get moving.</p></div><button class="primary" onclick="go('onboarding')">Open the demo →</button></div></div></section></div>`}

function landingLegacy(){return `<div class="landing"><h1>Orbit</h1></div>`}
function onboarding(){return `<div class="auth-wrap"><div class="auth-card onboarding-card">${logo(false)}<div class="eyebrow">Free interactive demo · Step 1 of 1</div><h1>Make Orbit yours.</h1><p>Tell us a little about what you want to accomplish. We’ll shape your first workspace around it.</p><div class="field"><label>What should we call you?</label><input id="onboarding-name" placeholder="Your name" value="${state.user.name||''}"></div><div class="field"><label>What are you using Orbit for?</label><select id="onboarding-use"><option value="school" ${state.user.useCase==='school'?'selected':''}>Planning my classes and assignments</option><option value="projects" ${state.user.useCase==='projects'?'selected':''}>Managing projects and deadlines</option><option value="habits" ${state.user.useCase==='habits'?'selected':''}>Building a consistent study habit</option><option value="other" ${state.user.useCase==='other'?'selected':''}>Something else</option></select></div><div class="field"><label>What would make this week feel successful?</label><textarea id="onboarding-goal" placeholder="e.g. Finish my research paper without cramming">${state.user.goal||''}</textarea></div><button class="primary" style="width:100%;padding:12px" onclick="finishOnboarding()">Create my free workspace →</button><div class="auth-foot">No payment or account setup required for this demo.</div></div></div>`}
function authLegacy(){return `<div class="auth-wrap"><div class="auth-card">${logo(false)}<h1>Welcome back</h1></div></div>`}
function appShell(){let nav=[['dashboard','Overview','grid'],['planner','Planner','check'],['roadmap','Roadmap','calendar'],['focus','Focus mode','target'],['courses','Courses','book'],['analytics','Analytics','chart']];return `<div class="app-shell"><aside class="sidebar">${logo()}<button class="workspace-switch" onclick="go('settings')"><span class="avatar">N</span><span><small>Workspace</small><strong>${state.org.name}</strong></span><span style="margin-left:auto">⌄</span></button><div class="nav-label">Workspace</div>${nav.map(n=>`<button class="nav-link ${view===n[0]?'active':''}" onclick="go('${n[0]}')">${icons[n[2]]}<span>${n[1]}</span></button>`).join('')}<div class="nav-label">Manage</div><button class="nav-link ${view==='settings'?'active':''}" onclick="go('settings')">${icons.settings}<span>Settings</span></button><div class="side-bottom"><div class="profile"><span class="avatar">MC</span><span class="profile-info"><b style="font-size:12px;color:#fff">${state.user.name}</b><small>${state.user.role} · Pro plan</small></span><span style="margin-left:auto;color:#7890b2">•••</span></div></div></aside><main class="main"><header class="topbar"><div class="crumb"><span>Workspace</span> <span style="margin:0 6px;color:#c1cad7">/</span> <strong>${({dashboard:'Overview',planner:'Assignment planner',roadmap:'Weekly roadmap',focus:'Focus mode',courses:'Courses',analytics:'Analytics',settings:'Settings'})[view]||'Overview'}</strong></div><div class="top-actions"><button class="icon-btn" onclick="toast('You are all caught up')">${icons.bell}</button><button class="secondary" onclick="openModal()">＋ Add task</button><button class="primary" onclick="go('focus')">${icons.target} Start focus</button></div></header><div class="content">${({dashboard:dashboard,planner:planner,roadmap:roadmap,focus:focus,courses:courses,analytics:analytics,settings:settings}[view]||dashboard)()}</div></main></div>`}
function dashboard(){let open=state.tasks.filter(t=>t.status!=='done');let done=state.tasks.filter(t=>t.status==='done').length;let rec=[...open].sort(score)[0];return `<div class="page-head"><div><div class="eyebrow">Saturday, October 10, 2026</div><h1>Good morning, Maya <span style="font-size:25px">✦</span></h1><p>Here's your clearest path to a productive day.</p></div><div class="page-actions"><button class="secondary" onclick="go('roadmap')">View weekly roadmap ${icons.calendar}</button><button class="primary" onclick="openModal()">＋ New assignment</button></div></div><div class="grid grid-4"><div class="card stat-card"><div class="stat-top">Open tasks <span>${icons.check}</span></div><div class="stat-value">${open.length}</div><div class="stat-foot"><span class="trend">↓ 2</span> from last week</div></div><div class="card stat-card"><div class="stat-top">On-time rate <span>${icons.target}</span></div><div class="stat-value">92%</div><div class="stat-foot"><span class="trend">↑ 8%</span> this semester</div></div><div class="card stat-card"><div class="stat-top">Focus this week <span>${icons.spark}</span></div><div class="stat-value">6h 20m</div><div class="stat-foot"><span class="trend">↑ 42m</span> vs last week</div></div><div class="card stat-card"><div class="stat-top">Semester progress <span>${icons.chart}</span></div><div class="stat-value">71%</div><div class="progress"><span style="width:71%"></span></div></div></div><div class="dash-grid"><div class="card"><div class="card-title"><h2>Today's priorities</h2><a onclick="go('planner')">See all ${icons.check}</a></div>${open.slice(0,4).map(taskRow).join('')}</div><div class="recommendation"><div class="rec-label">${icons.spark} &nbsp; Orbit recommends</div><h3>${rec.title}</h3><p>${reason(rec)}</p><div class="rec-meta"><span class="rec-dot"></span>${course(rec.course).name}<span>·</span>${rec.estimate} min</div><button class="rec-button" onclick="startTask('${rec.id}')">Start this task →</button></div></div><div class="dash-grid"><div class="card"><div class="card-title"><h2>This week's workload</h2><a onclick="go('roadmap')">Open roadmap →</a></div>${workload()}</div><div class="card"><div class="card-title"><h2>Coming up</h2><a onclick="go('planner')">View calendar →</a></div>${state.tasks.filter(t=>t.status!=='done').sort((a,b)=>a.due.localeCompare(b.due)).slice(0,3).map(t=>`<div class="deadline"><div class="date-tile"><b>${dateLabel(t.due).day}</b><span>${dateLabel(t.due).mon}</span></div><div style="flex:1"><div class="task-name">${t.title}</div><div class="task-sub"><span class="course-dot" style="background:${course(t.course).color}"></span>${course(t.course).code} · ${t.estimate} min</div></div><span class="pill ${t.priority.toLowerCase()}">${t.priority}</span></div>`).join('')}</div></div>`}
function taskRow(t){return `<div class="task-row"><button class="check ${t.status==='done'?'done':''}" onclick="toggleTask('${t.id}')">${t.status==='done'?icons.check:''}</button><div class="task-main"><div class="task-name ${t.status==='done'?'done-text':''}">${t.title}</div><div class="task-sub"><span class="course-dot" style="background:${course(t.course).color}"></span>${course(t.course).code} · Due ${dateLabel(t.due).full} · ${t.estimate} min</div></div><span class="pill ${t.priority.toLowerCase()}">${t.priority}</span></div>`}
function workload(){let days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'],hours=[2.2,3.5,1.4,4.1,2.8,1.7,1.1];return `<div class="workload-bars">${days.map((d,i)=>`<div class="bar-day"><b>${hours[i]}h</b><div class="bar ${d==='Sat'?'today':''}" style="height:${hours[i]*22}px"></div><span>${d}</span></div>`).join('')}</div>`}
function taskCategory(t){const value=(t.type||'Assignment').toLowerCase();return value.includes('study')||value.includes('read')?'studying':value.includes('project')||value.includes('essay')?'projects':'homework'}
function toggleWorkloadDetail(){workloadDetailed=!workloadDetailed;render()}
function workloadEnhanced(){if(!state.tasks.length)return '<div class="empty">Your weekly workload will appear here after you add assignments.</div>';const days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'],colors={homework:'#79a9ff',studying:'#31b982',projects:'#c29cff'},buckets=days.map(()=>({homework:0,studying:0,projects:0,tasks:[]}));state.tasks.filter(t=>t.status!=='done').forEach(t=>{const index=(new Date(t.due+'T12:00:00').getDay()+6)%7,bucket=buckets[index],category=taskCategory(t);bucket[category]+=Math.max(0,(t.estimate||0)/60);bucket.tasks.push(t)});const max=Math.max(...buckets.map(b=>b.homework+b.studying+b.projects),1);return '<div class="workload-header"><div class="workload-legend"><span><i style="background:'+colors.homework+'"></i>Homework</span><span><i style="background:'+colors.studying+'"></i>Studying</span><span><i style="background:'+colors.projects+'"></i>Projects</span></div><button class="detail-toggle '+(workloadDetailed?'active':'')+'" onclick="toggleWorkloadDetail()">'+(workloadDetailed?'Hide class details':'Show class details')+'</button></div><div class="workload-bars">'+days.map((d,i)=>{const b=buckets[i],total=b.homework+b.studying+b.projects;return '<div class="bar-day"><b>'+total.toFixed(1)+'h</b><div class="bar-stack" style="height:'+Math.max(8,total/max*112)+'px">'+['homework','studying','projects'].filter(k=>b[k]>0).map(k=>'<span style="height:'+(b[k]/max*112)+'px;background:'+colors[k]+'"></span>').join('')+'</div><span>'+d+'</span></div>'}).join('')+'</div>'+(workloadDetailed?'<div class="workload-detail">'+buckets.flatMap(b=>b.tasks).sort((a,b)=>a.due.localeCompare(b.due)).map(t=>'<div class="workload-detail-row"><span class="course-dot" style="background:'+course(t.course).color+'"></span><div><b>'+t.title+'</b><small>'+course(t.course).code+' · '+(t.type||'Homework')+' · '+t.estimate+' min</small></div><span class="pill '+t.priority.toLowerCase()+'">'+t.priority+'</span></div>').join('')+'</div>':'')}
function planner(){return `<div class="page-head"><div><div class="eyebrow">Your workload, made workable</div><h1>Assignment planner</h1><p>Every deadline in one calm, prioritized view.</p></div><button class="primary" onclick="openModal()">＋ Add assignment</button></div><div class="card"><div class="toolbar"><div class="search">${icons.search}<input id="task-search" placeholder="Search assignments..." oninput="filterTasks()"></div><div class="filters"><select id="course-filter" onchange="filterTasks()"><option value="all">All courses</option>${state.courses.map(c=>`<option value="${c.id}">${c.code}</option>`).join('')}</select><select id="status-filter" onchange="filterTasks()"><option value="all">All status</option><option value="todo">In progress</option><option value="done">Completed</option></select><select id="priority-filter" onchange="filterTasks()"><option value="all">All priority</option><option>High</option><option>Medium</option><option>Low</option></select></div></div><div id="task-table"><table class="table"><thead><tr><th style="width:40%">Assignment</th><th>Course</th><th>Due date</th><th>Time</th><th>Priority</th><th></th></tr></thead><tbody>${state.tasks.map(tableTask).join('')}</tbody></table></div></div>`}
function tableTask(t){return `<tr data-task data-course="${t.course}" data-status="${t.status}" data-priority="${t.priority}" data-search="${t.title.toLowerCase()}"><td><div class="task-cell"><button class="check ${t.status==='done'?'done':''}" onclick="toggleTask('${t.id}')">${t.status==='done'?icons.check:''}</button><span class="${t.status==='done'?'done-text':''}" style="font-weight:600">${t.title}</span></div></td><td><span class="course-chip"><span class="course-dot" style="background:${course(t.course).color}"></span>${course(t.course).code}</span></td><td>${dateLabel(t.due).full}</td><td>${t.estimate} min</td><td><span class="pill ${t.priority.toLowerCase()}">${t.priority}</span></td><td><button class="icon-btn" onclick="startTask('${t.id}')">${icons.target}</button></td></tr>`}
function filterTasks(){let q=(document.getElementById('task-search')?.value||'').toLowerCase(),c=document.getElementById('course-filter')?.value,s=document.getElementById('status-filter')?.value,p=document.getElementById('priority-filter')?.value;document.querySelectorAll('[data-task]').forEach(r=>r.style.display=(r.dataset.search.includes(q)&&(c==='all'||r.dataset.course===c)&&(s==='all'||r.dataset.status===s)&&(p==='all'||r.dataset.priority===p))?'':'none')}
function roadmap(){let days=[['Today','Sat · Oct 10',['Finalize market sizing analysis','Cognitive bias flashcards']],['Tomorrow','Sun · Oct 11',['Read chapters 7–8 + reflection']],['Monday','Mon · Oct 12',['Binary trees problem set','Prepare customer interview guide']],['Tuesday','Tue · Oct 13',['Deep work buffer · 90 min']]];return `<div class="page-head"><div><div class="eyebrow">Your next seven days</div><h1>Weekly roadmap</h1><p>A realistic plan that protects your energy and keeps deadlines visible.</p></div><button class="secondary" onclick="toast('Roadmap recalculated around your availability')">${icons.spark} Recalculate plan</button></div><div class="grid grid-3"><div class="card" style="grid-column:span 2"><div class="card-title"><h2>Recommended schedule</h2><span class="pill blue">12h 35m planned</span></div><div class="grid grid-2">${days.map(d=>`<div class="roadmap-day"><div class="roadmap-day-head"><strong>${d[0]}</strong><span>${d[1]}</span></div>${d[2].map((name,i)=>`<div class="roadmap-item"><span class="time">${i?'4:00':'10:00'}</span><div><b>${name}</b><div style="color:var(--muted);font-size:10px;margin-top:4px">${i?'25 min study block':'Deep work · 50 min'}</div></div></div>`).join('')}</div>`).join('')}</div></div><div class="card"><div class="card-title"><h2>Why this plan?</h2>${icons.spark}</div><div class="reason-box">Orbit prioritizes work that is both urgent and effort-heavy, then spaces it around your available study windows so no day exceeds 4 hours of planned work.</div><div style="margin-top:22px"><div class="stat-top">Weekly capacity <b style="color:var(--navy)">16h / 20h</b></div><div class="progress" style="margin-top:9px"><span style="width:80%"></span></div></div><div style="margin-top:22px"><div class="stat-top">Plan confidence <b style="color:var(--mint-strong)">High</b></div><p style="font-size:11px;line-height:1.6;color:var(--muted)">You have 7h 25m of buffer before your next major deadline.</p></div></div></div>`}
function focus(){let mins=Math.floor(timer.seconds/60).toString().padStart(2,'0'),secs=(timer.seconds%60).toString().padStart(2,'0');return `<div class="page-head"><div><div class="eyebrow">Protect your attention</div><h1>Focus mode</h1><p>One session. One task. Real progress.</p></div><button class="secondary" onclick="toast('Focus settings saved')">⚙ Session settings</button></div><div class="grid grid-2"><div class="focus-card card"><div class="timer">${mins}:${secs}</div><div class="timer-label">${timer.running?'Deep work in progress':'Ready when you are'}</div><div class="timer-controls"><button onclick="toggleTimer()">${timer.running?'Pause':'Start session'}</button><button class="secondary-dark" onclick="resetTimer()">Reset</button></div></div><div class="card"><div class="card-title"><h2>Current task</h2><span class="pill high">High priority</span></div><div style="font-family:'Space Grotesk';font-size:21px;color:var(--navy);line-height:1.2">Finalize market sizing analysis</div><div style="font-size:12px;color:var(--muted);margin-top:8px">Product Strategy · Due in 2 days</div><div style="margin-top:22px"><div class="stat-top">Assignment progress <b style="color:var(--navy)">40%</b></div><div class="progress" style="margin-top:9px"><span style="width:40%"></span></div></div><div style="margin-top:24px;background:#f7f9fc;border-radius:12px;padding:14px;font-size:12px"><b style="color:var(--navy)">Next step</b><p style="color:var(--muted);margin:6px 0 0;line-height:1.5">Validate the competitor benchmarks and add the source links to your analysis.</p></div><button class="primary" style="margin-top:18px" onclick="toast('Session note saved to market sizing analysis')">＋ Add session note</button></div></div><div class="grid grid-3" style="margin-top:18px"><div class="mini-stat"><span>Focus today</span><b>1h 40m</b><span class="trend">↑ 18m vs goal</span></div><div class="mini-stat"><span>This week</span><b>6h 20m</b><span>Goal: 8h</span></div><div class="mini-stat"><span>Sessions completed</span><b>12</b><span>Avg. 32 minutes</span></div></div>`}
function courses(){return `<div class="page-head"><div><div class="eyebrow">Your academic orbit</div><h1>Courses</h1><p>See the full shape of your semester at a glance.</p></div><button class="primary" onclick="toast('Course creation flow opened')">＋ Add course</button></div><div class="grid grid-3">${state.courses.map(c=>{let ts=state.tasks.filter(t=>t.course===c.id),pct=Math.round(ts.reduce((a,t)=>a+t.progress,0)/(ts.length||1));return `<div class="card course-card"><div class="course-banner" style="background:${c.color}"></div><h3>${c.name}</h3><p>${c.code} · ${c.teacher}</p><div style="margin-top:22px"><div class="stat-top">Course progress <b style="color:var(--navy)">${pct}%</b></div><div class="progress" style="margin-top:8px"><span style="width:${pct}%;background:${c.color}"></span></div></div><div class="course-meta"><span>${ts.length} assignments</span><span>Next: ${ts.sort((a,b)=>a.due.localeCompare(b.due))[0]?dateLabel(ts[0].due).full:'—'}</span></div></div>`}).join('')}</div>`}
function analytics(){return `<div class="page-head"><div><div class="eyebrow">Your momentum, measured</div><h1>Analytics</h1><p>Small patterns that help you build a better study week.</p></div><button class="secondary" onclick="toast('Report exported as PDF')">Export report ↓</button></div><div class="grid grid-4"><div class="card stat-card"><div class="stat-top">Assignments done</div><div class="stat-value">18</div><div class="stat-foot"><span class="trend">↑ 24%</span> vs last month</div></div><div class="card stat-card"><div class="stat-top">Focus time</div><div class="stat-value">21h 40m</div><div class="stat-foot"><span class="trend">↑ 12%</span> vs last month</div></div><div class="card stat-card"><div class="stat-top">On-time rate</div><div class="stat-value">92%</div><div class="stat-foot">Top 18% of your cohort</div></div><div class="card stat-card"><div class="stat-top">Deep work streak</div><div class="stat-value">6 days</div><div class="stat-foot"><span class="trend">Personal best</span> ✦</div></div></div><div class="dash-grid"><div class="card"><div class="card-title"><h2>Productivity trend</h2><span class="pill blue">Last 6 weeks</span></div><div style="height:220px;display:flex;align-items:flex-end;gap:17px;padding:15px 10px 0;border-bottom:1px solid var(--line)">${[40,58,46,72,66,88].map((h,i)=>`<div style="flex:1;height:100%;display:flex;align-items:center;flex-direction:column;justify-content:flex-end;gap:8px"><b style="font-size:10px;color:var(--muted)">${h/4}h</b><div style="width:100%;max-width:34px;height:${h*1.8}px;background:${i===5?'var(--navy)':'var(--lavender)'};border-radius:8px 8px 0 0"></div><span style="font-size:10px;color:var(--muted)">W${i+1}</span></div>`).join('')}</div></div><div class="card"><div class="card-title"><h2>Workload by course</h2></div>${state.courses.map((c,i)=>`<div style="margin:19px 0"><div class="stat-top"><span><span class="course-dot" style="background:${c.color}"></span>${c.code}</span><b>${[32,25,23,20][i]}%</b></div><div class="progress" style="margin-top:8px"><span style="width:${[32,25,23,20][i]}%;background:${c.color}"></span></div></div>`).join('')}</div></div>`}
function settings(){return `<div class="page-head"><div><div class="eyebrow">Workspace controls</div><h1>Settings</h1><p>Make Orbit fit the way your team studies and works.</p></div></div><div class="card"><div class="settings-nav"><button class="settings-tab active">Organization</button><button class="settings-tab" onclick="toast('Member management is ready')">Members</button><button class="settings-tab" onclick="toast('Billing is ready for Stripe integration')">Subscription</button></div><div class="grid grid-2"><div><h2 style="font-family:'Space Grotesk';font-size:17px;color:var(--navy)">Organization profile</h2><div class="field" style="margin:15px 0"><label>Workspace name</label><input value="${state.org.name}" onchange="state.org.name=this.value;save();toast('Workspace name updated')"></div><div class="field"><label>Academic timezone</label><select><option>Pacific Time (PT)</option><option>Eastern Time (ET)</option></select></div><button class="primary" style="margin-top:17px" onclick="toast('Organization preferences saved')">Save changes</button></div><div><h2 style="font-family:'Space Grotesk';font-size:17px;color:var(--navy)">Members <span class="pill blue">3 seats</span></h2><div class="member"><div class="member-info"><span class="avatar">MC</span><span><b>Maya Chen</b><br><span style="color:var(--muted);font-size:10px">maya@northstar.edu</span></span></div><span class="role">Owner</span></div><div class="member"><div class="member-info"><span class="avatar" style="background:var(--lavender)">JP</span><span><b>Jordan Patel</b><br><span style="color:var(--muted);font-size:10px">jordan@northstar.edu</span></span></div><span class="role">Member</span></div><button class="secondary" style="margin-top:15px" onclick="toast('Invite link copied to clipboard')">＋ Invite member</button></div></div></div><div class="card" style="margin-top:18px"><div class="card-title"><h2>Plan & usage</h2><span class="pill low">Pro · Active</span></div><div class="grid grid-3"><div class="mini-stat"><span>Tasks this month</span><b>24 / ∞</b></div><div class="mini-stat"><span>Focus sessions</span><b>12 / ∞</b></div><div class="mini-stat"><span>Members</span><b>3 / 10</b></div></div></div>`}
function openModal(){let m=document.createElement('div');m.className='modal-backdrop';m.id='modal';m.innerHTML=`<div class="modal"><h2>Add to your plan</h2><p>Orbit will automatically place this in your priority queue and weekly roadmap.</p><div class="form-grid"><div class="field full"><label>What needs doing?</label><input id="new-title" placeholder="e.g. Write literature review"></div><div class="field"><label>Course</label><select id="new-course">${state.courses.map(c=>`<option value="${c.id}">${c.code} · ${c.name}</option>`).join('')}</select></div><div class="field"><label>Due date</label><input id="new-due" type="date" value="2026-10-16"></div><div class="field"><label>Time estimate</label><select id="new-est"><option value="30">30 minutes</option><option value="60" selected>1 hour</option><option value="90">1.5 hours</option><option value="120">2 hours</option></select></div><div class="field"><label>Priority</label><select id="new-priority"><option>High</option><option selected>Medium</option><option>Low</option></select></div></div><div class="modal-foot"><button class="secondary" onclick="document.getElementById('modal').remove()">Cancel</button><button class="primary" onclick="addTask()">Add assignment →</button></div></div>`;document.body.appendChild(m)}
function addTask(){let title=document.getElementById('new-title').value.trim();if(!title){toast('Add a title to continue');return}state.tasks.push({id:'t'+Date.now(),title,type:'Assignment',course:document.getElementById('new-course').value,due:document.getElementById('new-due').value,estimate:+document.getElementById('new-est').value,difficulty:3,priority:document.getElementById('new-priority').value,status:'todo',progress:0,subtasks:1});save();document.getElementById('modal').remove();render();toast('Assignment added to your plan');if(state.tourStarted&&!state.tourComplete&&state.tasks.length===1){setTimeout(()=>showTour(2),400)}}
function toggleTask(id){let t=state.tasks.find(x=>x.id===id);t.status=t.status==='done'?'todo':'done';t.progress=t.status==='done'?100:Math.min(t.progress,80);save();render();toast(t.status==='done'?'Nice work — task complete':'Task reopened')}
function score(a,b){let urgency=x=>x.due<today?100:Math.max(0,20-(new Date(x.due)-new Date(today))/86400000*3);return (urgency(b)+b.difficulty*4+b.estimate/30+(100-b.progress)/20)-(urgency(a)+a.difficulty*4+a.estimate/30+(100-a.progress)/20)}function reason(t){let days=Math.ceil((new Date(t.due)-new Date(today))/86400000);return `Due in ${days} day${days===1?'':'s'}, needs about ${Math.round(t.estimate/60*10)/10} hours, and is ${t.progress}% complete. Starting now gives you enough buffer to finish without cramming.`}
function startTask(id){let t=state.tasks.find(x=>x.id===id);toast(`Focus session ready for “${t.title}”`);go('focus')}
function toggleTimer(){timer.running=!timer.running;if(timer.running){timer.interval=setInterval(()=>{timer.seconds--;if(timer.seconds<=0){clearInterval(timer.interval);timer.running=false;toast('Focus session complete — great work');}render()},1000)}else clearInterval(timer.interval);render()}
function resetTimer(){clearInterval(timer.interval);timer.running=false;timer.seconds=25*60;timer.preset=25;timer.mode='focus';timer.custom=false;render()}
function bind(){}
window.go=go;window.openModal=openModal;window.openImportModal=openImportModal;window.previewImport=previewImport;window.importAssignments=importAssignments;window.openCourseImportModal=openCourseImportModal;window.previewCourseImport=previewCourseImport;window.importCourses=importCourses;window.openClassModal=openClassModal;window.addClass=addClass;window.updateWeight=updateWeight;window.setNewPriorityAuto=setNewPriorityAuto;window.openShieldModal=openShieldModal;window.applyShield=applyShield;window.disableShield=disableShield;window.setTimer=setTimer;window.openCustomTimer=openCustomTimer;window.applyCustomTimer=applyCustomTimer;window.addTask=addTask;window.toggleTask=toggleTask;window.filterTasks=filterTasks;window.startTask=startTask;window.toggleTimer=toggleTimer;window.resetTimer=resetTimer;window.toggleWorkloadDetail=toggleWorkloadDetail;window.toast=toast;window.showTour=showTour;window.tourAction=tourAction;window.closeTour=closeTour;render();
